using System;
using System.Collections.Generic;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using UnityEditor.SceneManagement;
using SporeGobbo.Geometry.Preview.Editor;
namespace SporeGobbo.Geometry.Preview.Tests
{
 public class Stage53Tests
 {
  static LandmarkFixture fixture;static DiscoveryIndex index;
  [OneTimeSetUp]public void Setup(){fixture=new LandmarkFixture();index=new DiscoveryIndex(new StreamingWorld(1024,1024,47045,fixture),fixture.Regions);}
  sealed class Rig:IDisposable{public readonly StreamingWorld W;public readonly CaveDiscovery D;public readonly LandmarkPresentation P;public Rig(){W=new StreamingWorld(1024,1024,47045,fixture);D=new CaveDiscovery(W,index);D.SeedKnown(fixture.InitialKnown);P=new LandmarkPresentation(D);}public void Dispose()=>D.Dispose();}
  static bool Route(StreamingWorld w,Point2 a,Point2 b,int size,List<Point2> route=null)=>new LabNavigation(w,a).TraceToRoot(b,size,route??new List<Point2>());
  static void Complete(CaveDiscovery d){for(int i=0;i<30&&d.PendingReleases>0;i++)d.Tick(10);Assert.That(d.PendingReleases,Is.Zero);}
  static void Break(Rig r){r.W.Excavate(fixture.X+86,fixture.Y+19);r.D.ProcessChanges(fixture.P(86,24));}
  [Test]public void FootprintIsOnlyPhysicalStructureAuthority(){using(var r=new Rig()){foreach(var l in fixture.Landmarks)foreach(var c in l.Footprint){Assert.That(r.W.IsSolid(c.X,c.Y));Assert.That(r.W.Excavate(c.X,c.Y),Is.False);}Assert.That(r.W.IsSolid(fixture.X+45,fixture.Y),Is.False);Assert.That(r.W.Locked(fixture.X+45,fixture.Y),Is.False);}}
  [Test]public void SpikeStartsAtExactProtectedGroundContact(){var l=fixture.Landmarks[0];var a=l.Parts[0].Sections[0];Assert.That(a.Height,Is.Zero);Assert.That(l.Owns((int)a.Ground.X,(int)a.Ground.Y));Assert.That(a.Left.Y,Is.EqualTo(a.Ground.Y));Assert.That(l.Parts[0].Sections.Last().Radius,Is.Zero);}
  [Test]public void ArchesHaveSharedExactConnectionEdges(){var a=fixture.Landmarks[1].Parts[0].Sections.Last();var b=fixture.Landmarks[1].Parts[1].Sections[0];Assert.That(a.Ground,Is.EqualTo(b.Ground));Assert.That(a.Left,Is.EqualTo(b.Right));Assert.That(a.Right,Is.EqualTo(b.Left));Assert.That(a.Height,Is.Zero);}
  [Test]public void StructuralMeshesAreDeterministicNondegenerateAndCorrectWinding(){foreach(var l in fixture.Landmarks)foreach(var part in l.Parts)for(int side=0;side<2;side++){var a=new PreviewMeshData("a",PreviewLayer.Gobbo);var b=new PreviewMeshData("b",PreviewLayer.Gobbo);StructureMesh.Build(part,a,0,int.MaxValue,side==1);StructureMesh.Build(part,b,0,int.MaxValue,side==1);Assert.That(a.Vertices,Is.EqualTo(b.Vertices));Assert.That(a.Indices,Is.EqualTo(b.Indices));Assert.That(a.Indices.Count,Is.GreaterThan(0));for(int i=0;i<a.Indices.Count;i+=3)Assert.That(Vector3.Cross(a.Vertices[a.Indices[i+1]]-a.Vertices[a.Indices[i]],a.Vertices[a.Indices[i+2]]-a.Vertices[a.Indices[i]]).z,Is.LessThan(0));}}
  [TestCase(1)][TestCase(3)][TestCase(5)][TestCase(7)][TestCase(9)]public void WideRootPassageHasWholePhysicalRoute(int size){using(var r=new Rig()){var path=new List<Point2>();Assert.That(Route(r.W,fixture.P(45,14),fixture.P(45,-14),size,path));foreach(var p in path)Assert.That(PreviewMotion.Fits(r.W,Stage53Preview.V(p),size));}}
  [TestCase(1,true)][TestCase(3,true)][TestCase(5,true)][TestCase(7,false)][TestCase(9,false)]public void NarrowArchLocalClearanceIsNotWholeRouteCertification(int size,bool fits){using(var r=new Rig()){var nav=new LabNavigation(r.W,fixture.P(26,14));Assert.That(nav.Fits(fixture.P(26,0),size),Is.EqualTo(fits));Assert.That(Route(r.W,fixture.P(26,14),fixture.P(26,-14),size),"Alternate wide opening remains an actual route even when narrow opening is blocked");}}
  [Test]public void HiddenSpikeTipDoesNotDiscloseFloor(){using(var r=new Rig()){Assert.That(StructureMesh.GroundVisible(fixture.Landmarks[0],r.D),Is.False);Assert.That(fixture.Landmarks[0].Parts[0].ExposedTip);var p=fixture.P(-45,-18);Assert.That(r.W.IsSolid((int)p.X,(int)p.Y),Is.False);Assert.That(r.P.IsSolid((int)p.X,(int)p.Y));Assert.That(r.D.ContentAllowed(p,p),Is.False);}}
  [Test]public void SpikeCapAndLowerBodyShareExactSectionWithoutGap(){var p=fixture.Landmarks[0].Parts[0];var edge=p.Sections[18];var lower=new PreviewMeshData("lower",PreviewLayer.Gobbo);var upper=new PreviewMeshData("upper",PreviewLayer.Gobbo);StructureMesh.Build(p,lower,0,18);StructureMesh.Build(p,upper,18,24);Assert.That(lower.LogicalVertices.Any(v=>v.Logical.Equals(edge.Left)));Assert.That(upper.LogicalVertices.Any(v=>v.Logical.Equals(edge.Left)));}
  [Test]public void ProjectedBoundsContainEveryVertexForAllAnchors(){foreach(float a in Stage53Preview.Anchors){var map=new FocusProjection(fixture.P(44,14),52,28,30,.55,.12,1.9,new Point2(0,(a-.5)*49.09));foreach(var l in fixture.Landmarks)foreach(var part in l.Parts){var b=StructuralPrimitives.ProjectedBounds(part,map);foreach(var s in part.Sections)foreach(var q in new[]{s.Left,s.Right}){var v=map.Project(q);Assert.That(v.X,Is.InRange(b.Min.X,b.Max.X));Assert.That(v.Y,Is.InRange(b.Min.Y,b.Max.Y));}}}}
  [Test]public void ExposedTipBoundsExcludeHiddenBase(){var p=fixture.Landmarks[0].Parts[0];var data=new PreviewMeshData("cap",PreviewLayer.Gobbo);StructureMesh.Build(p,data,18,24);var b=StructureMesh.Bounds(data);Assert.That(b.Max.Y,Is.LessThan(p.Sections[0].Ground.Y-15));foreach(var v in data.LogicalVertices)Assert.That(v.Logical.Y,Is.InRange(b.Min.Y,b.Max.Y));}
  [Test]public void OverheadCutawayConsidersLargeSilhouetteRatherThanFeet(){var p=new FocusProjection(fixture.P(45,14),52,28,30,.55,.12,1.9,new Point2(0,0));var root=fixture.Landmarks[1].Parts[1];var body=fixture.P(45,2);var b=StructuralPrimitives.ProjectedBounds(root,p);Assert.That(p.Project(body).Y,Is.GreaterThan(b.Max.Y));Assert.That(StructureMesh.Occludes(b,p,body,Stage50Preview.VisualBounds(body,9,1),0));}
  [Test]public void FullBoundsIncludeAllVerticesAcrossChunks(){foreach(var l in fixture.Landmarks){Assert.That(l.MinChunk,Is.Not.EqualTo(l.MaxChunk));foreach(var part in l.Parts)foreach(var s in part.Sections)foreach(var p in new[]{s.Left,s.Right}){Assert.That(p.X,Is.InRange(l.Bounds.Min.X,l.Bounds.Max.X));Assert.That(p.Y,Is.InRange(l.Bounds.Min.Y,l.Bounds.Max.Y));}}}
  [Test]public void OffscreenGroundCanHaveVisibleTallBody(){var part=fixture.Landmarks[0].Parts[0];var ground=part.Sections[0].Ground;var map=new FocusProjection(new Point2(ground.X,ground.Y-35),52,28,30,.55,.12,1.9,new Point2(0,0));var projected=StructuralPrimitives.ProjectedBounds(part,map);var view=new ProjectionBounds(new Point2(-44,-24),new Point2(44,24));Assert.That(map.Project(ground).Y,Is.GreaterThan(24));Assert.That(StructuralPrimitives.Intersects(projected,view));}
  [Test]public void HybridAcceleratesOnlyGeodesicEntranceWithoutExpandingMemory(){using(var a=new Rig())using(var b=new Rig()){b.D.ImmediateDistance=5;Break(a);Break(b);a.D.Tick(0);b.D.Tick(0);Assert.That(b.D.Remembered,Is.EquivalentTo(a.D.Remembered));Assert.That(b.D.Visual.Count,Is.GreaterThan(a.D.Visual.Count));Assert.That(b.D.Known(fixture.X,fixture.Y-42),Is.False);Complete(a.D);Complete(b.D);Assert.That(a.D.Visual,Is.EquivalentTo(b.D.Visual));}}
  [Test]public void SoftFrontierOnlySuppressesSyntheticDepthAndNeverPhysicalWalls(){using(var r=new Rig()){r.P.Style=BreakthroughStyle.Soft;Break(r);r.D.Tick(.1);int soft=0;foreach(int i in r.D.Visual)if(r.P.SoftTile(i%1024,i/1024))soft++;Assert.That(soft,Is.GreaterThan(0));Assert.That(r.P.SoftTile(fixture.X+20,fixture.Y),Is.False);}}
  [Test]public void PhysicalBreakthroughAndRoutesDoNotWaitForAnimation(){using(var r=new Rig()){Break(r);Assert.That(r.D.PendingReleases,Is.GreaterThan(0));Assert.That(Route(r.W,fixture.P(86,24),fixture.P(86,-20),1));Assert.That(r.P.IsSolid(fixture.X+86,fixture.Y-20));}}
  [Test]public void PointClearanceDoesNotProveNarrowEntranceConnectivity(){using(var r=new Rig()){Break(r);var a=fixture.P(86,24);var b=fixture.P(86,-12);var nav=new LabNavigation(r.W,a);Assert.That(nav.Fits(b,3));Assert.That(Route(r.W,a,b,1));Assert.That(Route(r.W,a,b,3),Is.False);r.W.Excavate(fixture.X+85,fixture.Y+19);r.W.Excavate(fixture.X+87,fixture.Y+19);Assert.That(Route(r.W,a,b,3));}}
  [Test]public void SpikeCanBeCircumnavigatedAndDirtCollarExcavatedLocally(){using(var r=new Rig()){var a=fixture.P(-55,-10);var b=fixture.P(-35,-10);Assert.That(Route(r.W,a,b,1));Assert.That(r.W.Excavate(fixture.X-50,fixture.Y-10));Assert.That(r.W.Excavate(fixture.X-45,fixture.Y-10),Is.False);Assert.That(Route(r.W,a,b,1));}}
  [Test]public void DiggingActualShortcutChangesConnectivityWithoutFootprintBypass(){using(var r=new Rig()){var a=fixture.P(-2,24);var b=fixture.P(9,24);Assert.That(Route(r.W,a,b,1),Is.False);for(int x=3;x<=5;x++)Assert.That(r.W.Excavate(fixture.X+x,fixture.Y+24));Assert.That(Route(r.W,a,b,1));Assert.That(r.W.Excavate(fixture.X+20,fixture.Y),Is.False);}}
  [TestCase(0)][TestCase(1)][TestCase(2)]public void AnchorChangesOffsetOnlyAndPreservesScale(int n){var a=Stage49Preview.Settings(2);double h=(a.centerWidth/a.coverage)/(16.0/9);var p=new FocusProjection(fixture.P(45,14),52,28,30,.55,.12,1.9,new Point2(0,(Stage53Preview.Anchors[n]-.5)*h));Assert.That(.5+p.Project(p.Focus).Y/h,Is.EqualTo(Stage53Preview.Anchors[n]).Within(1e-7));Assert.That(p.ScaleY(p.Focus.Y+30),Is.EqualTo(new FocusProjection(p.Focus,52,28,30,.55,.12,1.9,new Point2(0,0)).ScaleY(p.Focus.Y+30)));Assert.That(p.Unproject(p.Project(fixture.P(1,2))).Y,Is.EqualTo(fixture.P(1,2).Y).Within(1e-8));}
  [Test]public void CompletedSoftGeometryEqualsCanonicalPhysicalMesh(){using(var r=new Rig()){r.P.Style=BreakthroughStyle.Soft;foreach(var region in index.Regions)r.D.SeedKnown(region.Cells);var a=PreviewMeshBuilder.BuildPatch(r.P,new ContourTerrainCache(r.P),528,496,16);var b=PreviewMeshBuilder.BuildPatch(r.W,new ContourTerrainCache(r.W),528,496,16);for(int i=0;i<4;i++){Assert.That(a[i].Vertices,Is.EqualTo(b[i].Vertices));Assert.That(a[i].Indices,Is.EqualTo(b[i].Indices));}}}
  [Test]public void RepeatedResetOwnsTenMeshesAndCameraDoesNotRebuildTopology(){Stage53Tools.Install();var go=UnityEngine.Object.FindAnyObjectByType<Stage53Preview>();go.Initialize();for(int r=0;r<3;r++){go.ResetDemo();Assert.That(go.OwnedMeshes,Is.EqualTo(10));Assert.That(go.FrontierVertices,Is.Zero);Assert.That(go.GetComponentsInChildren<MeshFilter>().Count(x=>x.name.StartsWith("Stage53 structure batch")),Is.EqualTo(10));}int builds=go.StructureBuilds;for(int n=0;n<3;n++){go.SetAnchor(n);go.Live.Refresh(1f/60);}Assert.That(go.StructureBuilds,Is.EqualTo(builds));Assert.That(go.GetComponent<Stage52Preview>(),Is.Null);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);}
 }
}
